css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px 12px; margin-bottom: 10px;}
.mz .recuerda-titulo{font-size: 14px; font-weight: 700; margin-bottom: 5px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 14px; margin-bottom: 6px; line-height: 1.35;}
.mz .recuerda-idea strong{font-weight: 700;}
.mz .recuerda-tabla{display: grid; grid-template-columns: 1fr 1fr; gap: 2px 24px;}
.mz .recuerda-item{font-size: 14px; font-weight: 600; padding: 1px 0; display: flex; align-items: center;}
.mz .recuerda-item .arrow{margin: 0 8px; font-weight: 700; font-family: sans-serif;}
.mz .lin-fila{display: grid; grid-template-columns: 1fr 65px; gap: 10px; padding: 3px 10px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 3px; align-items: center;}
.mz .lin-texto{font-size: 15px; font-weight: 600;}
.mz .lin-texto .hueco{display: inline-block; min-width: 30px; border-bottom: 1.5px solid var(--bosque); margin: 0 4px;}
.mz .lin-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 26px;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .recuerda-idea{line-height: 1.875 !important;}
